func TestBoundedReaderControlProfileOnlyBudgetLines(t *testing.T) {
	got, err := profile(controlRaw())
	if err != nil {
		t.Fatal(err)
	}
	if got != string(controlCommitted()) {
		t.Fatal("profile must equal the independent fixture with only the two budget integers lowered")
	}
	if strings.TrimPrefix(got, controlProfiledPrefix) != controlDeclarations+controlEnd {
		t.Fatal("profile changed bytes after the required header")
	}
}

