func TestBoundedReaderControlProfileByteCap(t *testing.T) {
	// The exact boundary is admitted by this byte/profile guard. The contents
	// are padding, not a generated-program or Lean-validity claim.
	padding := 64<<10 - len(controlRawPrefix) - len(controlEnd)
	raw := controlRawPrefix + strings.Repeat(" ", padding) + controlEnd
	if _, err := profile(raw); err != nil {
		t.Fatalf("exact 64 KiB profile boundary refused: %v", err)
	}
	_, err := profile(controlRawPrefix + strings.Repeat(" ", padding+1) + controlEnd)
	controlError(t, err, "generated prefix/encoding/bound differs")
}

