func TestBoundedReaderControlCollidingResultCarrier(t *testing.T) {
	insts := controlInstantiations()
	// Public Instantiation.MangledName joins atoms with underscores. These
	// distinct synthetic atom vectors intentionally produce the same name.
	collision := typechecker.Instantiation{ADT: "Result", Args: []string{"encoding", "sreader__Window_encoding_sreader__Error"}}
	if collision.MangledName() != insts[0].MangledName() {
		t.Fatal("collision fixture no longer produces the required carrier name")
	}
	insts = append(insts, collision)
	_, _, err := expectedTypes(insts)
	controlError(t, err, "aliased checked Result carrier")
}

