func TestBoundedReaderControlDriftRefusesChangedRawHeader(t *testing.T) {
	raw := controlReplace(t, controlRaw(), "maxHeartbeats 4000000", "maxHeartbeats 4000001")
	controlError(t, compareProfiled(raw, controlCommitted()), "generated prefix/encoding/bound differs")
}

func TestBoundedReaderControlExactRawProfiledSpans(t *testing.T) {
    _,_,blocks:=controlInventory(t)
    raw:=controlRaw();profiled:=string(controlCommitted());shift:=len(profiled)-len(raw)
    total:=0
    for name,block:=range blocks {
        start,end,err:=generatedSpan(raw,name);if err!=nil{t.Fatal(err)}
        if start<len(controlRawPrefix)||end<=start||end>len(raw)-len(controlEnd){t.Fatal("raw span outside body")}
        span:=raw[start:end]
        if strings.TrimRight(span,"\n")+"\n"!=block{t.Fatalf("raw span mismatch for %s",name)}
        if profiled[start+shift:end+shift]!=span{t.Fatalf("profiled span bytes changed for %s",name)}
        total+=end-start
    }
    if total!=len(controlDeclarations){t.Fatalf("raw spans cover %d bytes, want %d",total,len(controlDeclarations))}
}

func TestBoundedReaderControlMissingRawSpan(t *testing.T) {
    _,_,err:=generatedSpan(controlRaw(),"absent")
    controlError(t,err,"missing raw span")
}

func TestBoundedReaderControlDuplicateRawSpan(t *testing.T) {
    raw:=controlRawPrefix+controlDeclarations+"def bytes__range_ufits : Nat := 0\n"+controlEnd
    _,_,err:=generatedSpan(raw,controlRange)
    controlError(t,err,"duplicate raw span")
}
